import { DivFlexColumn, DivFlexRow, StyledLabel } from "./elements/formelements";
import ButtonDisabledDuringAction from "./ButtonDisabledDuringAction";

interface ButtonWithLabelProps {
    label: string;
    buttonCaption: string;
    onPress: () => void | Promise<void>;
    disabled?: boolean;
}

const ButtonWithLabel: React.FC<ButtonWithLabelProps> = ({ label, buttonCaption, onPress, disabled }) => {
    return (
        <DivFlexRow>
            <DivFlexColumn>
                <StyledLabel>{label}</StyledLabel>
            </DivFlexColumn>
            <DivFlexColumn>
                <ButtonDisabledDuringAction onPress={onPress} buttonCaption={buttonCaption} disabled={disabled} />
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default ButtonWithLabel;
